styles:
/* presentation.css deja html/body en `overflow:hidden` porque el shell de
       docs scrollea dentro de `.main`. Esta página no usa ese shell, así que el
       scroll lo tiene que aportar ella: columna de alto fijo + panel scrollable.
       Sin esto la lista de iconos se corta y no hay forma de bajar. */
    html, body { height: 100%; overflow: hidden; }
    is-main { display: flex; flex-direction: column; height: 100%; min-height: 0; }

    .xp {
      flex: 1;
      min-height: 0;
      overflow-y: auto;
      overscroll-behavior: contain;
      scrollbar-width: thin;
      scrollbar-color: var(--is-scrollbar-thumb) transparent;
      padding: 20px clamp(16px, 3vw, 32px) 96px;
    }
    .xp-inner { max-width: 1180px; margin: 0 auto; }

    .xp-head { display: flex; align-items: baseline; gap: 0.75rem; flex-wrap: wrap; }
    .xp-head h1 { margin: 0 0 4px; font-size: 1.5rem; }
    .xp-head .count { color: var(--is-text-soft); font-size: 0.8rem; }

    /* — buscador + filtros —
       Los controles son <is-input>, <is-select> y <is-button-group>: no se
       replican inputs nativos con estilos propios. */
    .xp-bar {
      position: sticky;
      top: 0;
      z-index: 4;
      padding: 12px 0 10px;
      background: linear-gradient(var(--is-bg) 78%, transparent);
      display: grid;
      gap: 10px;
    }
    .xp-bar__search { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
    .xp-bar__search is-input { flex: 1; min-width: 240px; }
    .filters { display: flex; gap: 8px; flex-wrap: wrap; align-items: end; }
    .filters is-select { min-width: 150px; }

    /* — vista familias — */
    .fam-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 10px; }
    .fam { display: block; color: inherit; text-decoration: none; }
    .fam:hover { text-decoration: none; }
    .fam is-card { transition: border-color 140ms ease, transform 140ms ease; }
    .fam:hover is-card { border-color: var(--is-accent); transform: translateY(-1px); }
    .fam b { font-size: 0.95rem; }
    .fam small { color: var(--is-text-soft); font-size: 0.75rem; }
    .fam .sample { display: flex; gap: 8px; font-size: 1.2rem; color: var(--is-text-soft); min-height: 1.3em; margin: 6px 0; }
    .fam .meta { display: flex; gap: 4px; flex-wrap: wrap; }

    /* — rejilla de iconos — */
    .tools { display: flex; align-items: end; gap: 0.9rem; flex-wrap: wrap; }
    .tools is-slider { min-width: 180px; }
    .icon-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 8px; }
    .icon-cell {
      display: grid;
      justify-items: center;
      gap: 6px;
      padding: 12px 6px 8px;
      border: 1px solid transparent;
      border-radius: 0.55rem;
      background: transparent;
      color: inherit;
      font: inherit;
      cursor: pointer;
      transition: background 120ms ease, border-color 120ms ease;
    }
    .icon-cell:hover { background: var(--is-bg-elev); border-color: var(--is-border); }
    .icon-cell.sel { border-color: var(--is-accent); background: color-mix(in srgb, var(--is-accent) 10%, transparent); }
    .icon-cell is-icon { font-size: var(--xp-size, 1.6rem); color: var(--xp-color, currentColor); }
    .icon-cell small {
      max-width: 100%;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      font-size: 0.7rem;
      color: var(--is-text-soft);
    }
    .icon-cell .fam-tag { font-size: 0.7rem; color: var(--is-accent); }
    .more { margin: 18px auto; display: block; }
    .empty { color: var(--is-text-soft); padding: 32px 0; text-align: center; }
    .status { display: grid; gap: 8px; padding: 32px 0; justify-items: center; }
    .status is-progress-bar { width: min(360px, 100%); }

    /* — contenido del drawer de personalización — */
    .form__meta { display: grid; gap: 2px; margin-bottom: 10px; }
    .form__idrow { display: flex; align-items: center; gap: 0.4rem; }
    .form__idrow b { font-size: 1rem; word-break: break-all; }
    .form__sub { font-size: 0.75rem; color: var(--is-text-soft); }
    .preview {
      display: grid;
      place-items: center;
      min-height: 150px;
      border: 1px solid var(--is-border);
      border-radius: 0.5rem;
      /* Tablero para comprobar visualmente el área completa del icono. */
      background-color: var(--is-bg);
      background-image:
        linear-gradient(45deg, var(--is-border-soft) 25%, transparent 25%),
        linear-gradient(-45deg, var(--is-border-soft) 25%, transparent 25%),
        linear-gradient(45deg, transparent 75%, var(--is-border-soft) 75%),
        linear-gradient(-45deg, transparent 75%, var(--is-border-soft) 75%);
      background-size: 16px 16px;
      background-position: 0 0, 0 8px, 8px -8px, -8px 0;
      overflow: auto;
      padding: 12px;
      margin-bottom: 12px;
    }
    .preview__box { outline: 1px dashed color-mix(in srgb, var(--is-accent) 55%, transparent); outline-offset: 2px; line-height: 0; }
    .preview__box svg { display: block; }

    .row { display: flex; gap: 8px; flex-wrap: wrap; align-items: end; margin-bottom: 10px; }
    .row--grow is-input, .row--grow is-select { flex: 1; min-width: 130px; }
    .checks { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 12px; }
    .code {
      margin: 0;
      padding: 10px 12px;
      max-height: 240px;
      overflow: auto;
      border-radius: 0.45rem;
      background: var(--is-code-bg, #0f1318);
      color: var(--is-code-text, #d4d8de);
      font-family: var(--is-mono, ui-monospace, monospace);
      font-size: 0.75rem;
      line-height: 1.5;
      white-space: pre;
    }
    .code__head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 4px; }
    .code__head span { font-size: 0.75rem; color: var(--is-text-soft); }
